// An installed package, as far as Pudding can tell. `keep` only reads what it
// is given. `touch` changes it, which its types allow for a mutable table.
export function keep(table) {
  return table
}

export function touch(table) {
  table.usd = "changed"
  return table
}

export function touchInner(table) {
  table.inner.usd = "changed"
  return table
}
